217:   function naughtyHref(name, href) {
218:     // Browsers ignore character codes of 32 (space) and below in a surprising
219:     // number of situations. Start reading here:
220:     // https://www.owasp.org/index.php/XSS_Filter_Evasion_Cheat_Sheet#Embedded_tab
221:     href = href.replace(/[\x00-\x20]+/g, '');
222:     // Clobber any comments in URLs, which the browser might
223:     // interpret inside an XML data island, allowing
224:     // a javascript: URL to be snuck through
225:     href = href.replace(/<\!\-\-.*?\-\-\>/g, '');
226:     // Case insensitive so we don't get faked out by JAVASCRIPT #1
