242:     if (!allowed) {
243:       // The class attribute is allowed without filtering on this tag
244:       return classes;
245:     }
246:     classes = classes.split(/\s+/);
247:     return classes.filter(function(clss) {
248:       return allowed.indexOf(clss) !== -1;
249:     }).join(' ');
